from PIL import Image, ImageOps
import numpy as np
im = Image.open('radiograph.jpg').convert('L')
a = np.asarray(im).astype(np.float32)
def stretch(c):
    lo,hi = np.percentile(c,2), np.percentile(c,98)
    return Image.fromarray(np.clip((c-lo)/(hi-lo)*255,0,255).astype(np.uint8))
crops = {
 'm_lowR': (1430,780,1720,1010),
 'm_lowL': (600,720,900,980),
 'm_lowR2': (1650,780,1950,1050),
}
for k,(x1,y1,x2,y2) in crops.items():
    c = a[y1:y2,x1:x2]
    img = stretch(c)
    img = img.resize((img.width*5,img.height*5), Image.LANCZOS)
    img.save(f'm_{k}.png'); print(k, img.size)
